-- Şema — CLAUDE_CODE_BRIEF.md §6. Idempotent (IF NOT EXISTS); her açılışta çalışır.
-- TAŞINABİLİR (Faz 9d, ADR-0014): AYNI dosya H2 (yerel/mcp) ve PostgreSQL'de (site) çalışır.
-- Kurallar: kimlik kolonu BIGINT GENERATED BY DEFAULT AS IDENTITY (H2'ye özgü IDENTITY tipi DEĞİL),
-- uzun metin TEXT (CLOB DEĞİL; H2'de TEXT = CLOB eş adı), ALTER ... ADD CONSTRAINT IF NOT EXISTS YOK
-- (PostgreSQL desteklemez → CREATE UNIQUE INDEX IF NOT EXISTS). SemaTasinabilirlikTest bunları zorlar.
--
-- Faz 2a-3: KULLANICI-KİMLİKLİ İZOLASYON (ADR-0008). Dört ilerleme tablosuna kullanici_id
-- eklendi (VARCHAR(255) NOT NULL DEFAULT 'yerel'). Böylece mevcut TEK-KULLANICI veri kaybolmaz:
-- kolon eklendiğinde mevcut satırlar otomatik 'yerel' değerini alır (web profili = tek kullanıcı).
-- mcp-http (JWT) profilinde her kullanıcı kendi email/sub'ı ile izole olur.
--
-- MİGRASYON STRATEJİSİ (hem yeni kurulum hem MEVCUT data/ogrenme dosya DB'si çalışsın):
--   * Yeni kurulum: aşağıdaki CREATE TABLE ... zaten kullanici_id + doğru UNIQUE ile kurar.
--   * Mevcut DB: CREATE TABLE IF NOT EXISTS mevcut tabloyu ATLAR → kolonu ALTER ... ADD COLUMN
--     IF NOT EXISTS ekler; eski (kullanıcısız) UNIQUE kısıtı düşürülüp kullanıcıya-bölünmüş
--     yenisi eklenir. Tüm ifadeler IF [NOT] EXISTS ile idempotent — her açılışta güvenle çalışır.
-- ai_kullanim: Faz 9b'de (ADR-0012) kullanici_id aldı — çok kullanıcılı sitede /api/kullanim yalnız kendi
-- çağrılarını gösterir; eski satırlar 'yerel' olur (aynı ADD COLUMN IF NOT EXISTS deseni).

CREATE TABLE IF NOT EXISTS gorev_ilerleme (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  hafta INT NOT NULL, gun INT NOT NULL, gorev_index INT NOT NULL,
  tamamlandi BOOLEAN NOT NULL DEFAULT FALSE,
  tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
-- Mevcut DB migrasyonu (yeni kurulumda no-op):
ALTER TABLE gorev_ilerleme ADD COLUMN IF NOT EXISTS kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel';
-- Eski kullanıcısız UNIQUE(hafta,gun,gorev_index) — H2 otomatik adı CONSTRAINT_BB — çok kullanıcıyı
-- engeller (iki kullanıcı aynı görevi işaretleyemezdi); düşür. IF EXISTS → yeni kurulumda no-op.
ALTER TABLE gorev_ilerleme DROP CONSTRAINT IF EXISTS CONSTRAINT_BB;
-- Kullanıcıya-bölünmüş benzersizlik (yeni ve eski DB için TEK yol). PostgreSQL'de "ADD CONSTRAINT IF NOT
-- EXISTS" YOK (Faz 9d, ADR-0014) → taşınabilir eşdeğer: benzersiz indeks. ADR-0008 dönemi H2 dosyalarında
-- ayrıca eski uq_gorev_ilerleme_kullanici kısıtı durur (aynı kolonlar; zararsız tekrar).
CREATE UNIQUE INDEX IF NOT EXISTS ux_gorev_ilerleme_kullanici
  ON gorev_ilerleme (kullanici_id, hafta, gun, gorev_index);

CREATE TABLE IF NOT EXISTS gonderim (            -- kullanıcının yazdığı özet/cevap/iş (Faz 2)
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  hafta INT NOT NULL, gun INT,
  tur VARCHAR(20) NOT NULL,                       -- OZET | GOREV_CIKTISI | SORU_CEVABI
  icerik TEXT NOT NULL,
  degerlendirme_json TEXT,
  puan INT,
  tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE gonderim ADD COLUMN IF NOT EXISTS kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel';
CREATE INDEX IF NOT EXISTS ix_gonderim_kullanici_hafta ON gonderim (kullanici_id, hafta);

CREATE TABLE IF NOT EXISTS quiz_sonuc (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  hafta INT NOT NULL,
  tur VARCHAR(10) NOT NULL,                       -- STATIK | AI_URETIM
  puan INT NOT NULL,
  detay_json TEXT,
  tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE quiz_sonuc ADD COLUMN IF NOT EXISTS kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel';
CREATE INDEX IF NOT EXISTS ix_quiz_sonuc_kullanici_hafta ON quiz_sonuc (kullanici_id, hafta);

CREATE TABLE IF NOT EXISTS sohbet_mesaj (         -- Faz 2
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  hafta INT NOT NULL,
  rol VARCHAR(10) NOT NULL,                       -- USER | ASSISTANT
  icerik TEXT NOT NULL,
  tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE sohbet_mesaj ADD COLUMN IF NOT EXISTS kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel';
CREATE INDEX IF NOT EXISTS ix_sohbet_mesaj_kullanici_hafta ON sohbet_mesaj (kullanici_id, hafta);

CREATE TABLE IF NOT EXISTS mulakat_cevap (        -- Faz 1 (Mülakat): kullanıcının soru cevapları
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  soru_id VARCHAR(100) NOT NULL, alan_slug VARCHAR(100) NOT NULL, konu_slug VARCHAR(100) NOT NULL,
  secilen_index INT NOT NULL, dogru BOOLEAN NOT NULL, tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
-- Ana sorgu: kullanıcının cevapları tarih DESC (hataliSorularTekrar); id DESC tie-break sorgu tarafında.
CREATE INDEX IF NOT EXISTS ix_mulakat_cevap_kullanici_tarih ON mulakat_cevap (kullanici_id, tarih DESC);

CREATE TABLE IF NOT EXISTS ai_kullanim (           -- token/maliyet takibi (brief 7.6)
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel',
  islem VARCHAR(30) NOT NULL,                     -- DEGERLENDIRME | SOHBET | HAFIZA | QUIZ | RAPOR | MULAKAT
  model VARCHAR(50) NOT NULL,
  input_tokens INT NOT NULL DEFAULT 0,
  output_tokens INT NOT NULL DEFAULT 0,
  sure_ms INT,                                    -- çağrının duvar saati süresi (yeniden denemeler dahil)
  yanit_model VARCHAR(100),                       -- sağlayıcının cevapta bildirdiği model (yedeğe geçiş görünür)
  tarih TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
-- Faz 9b: mevcut DB migrasyonu (yeni kurulumda no-op). H2 + PostgreSQL ikisi de ADD COLUMN IF NOT EXISTS destekler.
ALTER TABLE ai_kullanim ADD COLUMN IF NOT EXISTS kullanici_id VARCHAR(255) NOT NULL DEFAULT 'yerel';
-- ADR-0016 (2026-10-26): gecikme + cevaptaki model; nullable — eski satırlar boş kalır.
ALTER TABLE ai_kullanim ADD COLUMN IF NOT EXISTS sure_ms INT;
ALTER TABLE ai_kullanim ADD COLUMN IF NOT EXISTS yanit_model VARCHAR(100);
CREATE INDEX IF NOT EXISTS ix_ai_kullanim_kullanici ON ai_kullanim (kullanici_id, islem);

-- Faz 9a — KİMLİK (ADR-0012): yalnız `site` profilinde kullanılır; yerel modda tablolar boş durur.
-- Taşınabilir SQL (H2 bugün, PostgreSQL 9d'de): IDENTITY yerine standart GENERATED BY DEFAULT AS IDENTITY,
-- CREATE ... IF NOT EXISTS (ikisi de destekler). email küçük harfe çevrilmiş saklanır → UNIQUE yeterli.
-- email aynı zamanda ilerleme tablolarındaki kullanici_id izolasyon kimliğidir (ADR-0008 ile tutarlı).
CREATE TABLE IF NOT EXISTS kullanici (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email VARCHAR(320) NOT NULL,
  sifre_hash VARCHAR(100) NOT NULL,                 -- BCrypt ($2a$10$...), düz şifre ASLA
  dogrulandi BOOLEAN NOT NULL DEFAULT FALSE,        -- e-posta doğrulanmadan giriş yok
  etkin BOOLEAN NOT NULL DEFAULT TRUE,              -- hesap kapatma (işten ayrılan): FALSE
  olusturma TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  basarisiz_deneme INT NOT NULL DEFAULT 0,          -- kaba kuvvet sayacı (5 → kilit)
  kilit_bitis TIMESTAMP,                            -- NULL = kilitsiz
  CONSTRAINT uq_kullanici_email UNIQUE (email)
);

-- Süreli, tek kullanımlık token'lar (e-posta doğrulama; 9c: şifre sıfırlama). Ham token saklanmaz,
-- yalnız SHA-256 özeti (hex). Hesap silinince token'ları da gider (ON DELETE CASCADE).
CREATE TABLE IF NOT EXISTS kullanici_token (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  hesap_id BIGINT NOT NULL REFERENCES kullanici (id) ON DELETE CASCADE,
  tur VARCHAR(20) NOT NULL,                         -- DOGRULAMA | SIFRE_SIFIRLAMA (9c)
  token_hash VARCHAR(64) NOT NULL,
  son_gecerlilik TIMESTAMP NOT NULL,
  olusturma TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_kullanici_token_hash UNIQUE (token_hash)
);
CREATE INDEX IF NOT EXISTS ix_kullanici_token_hesap ON kullanici_token (hesap_id, tur);
